Senda.Knowledge:Register({
  id = "general-professions-guide",
  class = "ANY",
  kind = "page",
  title = "Profesiones: Sastrería y Encantamiento",
  order = 190,
  status = "unverified",
  note = "Recomendación de Legacy (Thrill of Adventure) según ConquestCapped. Los nombres de Legacy y Arcane Salvager están en inglés: el nombre español no está confirmado.",
  block = {
    { heading = "Plan definitivo", body = "**Sastrería + Encantamiento**, sin cambiar nunca. Secundarias: Primeros auxilios y Cocina (Pesca opcional).\n\nCada profesión de fabricación da 1 punto de Legacy a 150, 225 y 300, una vez por cuenta. Subirla de nuevo no da nada." },
    { heading = "Rangos de instructor", body = "- **Aprendiz:** 1-75.\n- **Oficial:** habilidad 50 y nivel 10.\n- **Experto:** habilidad 125 y nivel 20.\n- **Artesano:** habilidad 200 y nivel 35.\n\nEntrena el rango siguiente antes de llegar al tope: los puntos por encima se pierden." },
    { heading = "Sastrería por habilidad", body = "- **1-45:** Madejas de paño de lino; **45-55:** Guantes de lino pesado.\n- **20:** Estandarte de facción para el campamento (+Espíritu).\n- **60-125:** conjuntos nuevos ligados al recogerlos (30 de Favor cada patrón, Mivin Shadowweave en Tres Caminos). Fabrica el de Sombras si eres brujo.\n- **75-125:** túnicas Filigreed (Filigreed Shadow Gown para Aflicción); patrones en jefes de mazmorra.\n- **140:** Rueca para el campamento (patrón de botín, no del instructor). **140-235:** seis conjuntos más; los pies son de lo mejor a los niveles 30, 40 y 50.\n- **195-205:** hombros y brazales Nether (60 de Favor y Amistoso con la Azeroth Commerce Authority).\n- **300:** Telar y conjunto de banda del brujo (Demonheart, Aisarra Nightmeadow).\n\nRuta exacta con materiales: data/knowledge/general/professions-tailoring.toml. De 225 a 300 aún no hay ninguna ruta probada en Forever." },
    { heading = "Encantamiento por habilidad", body = "- **1:** Vara de cobre con runas, y desencanta todo verde que no uses.\n- **Varita mágica inferior:** la receta se aprende a 10; haz una para ti ya. **Varita mágica superior:** a 70. Para subir puntos rinden más tarde (70-90 y 101-111).\n- **20:** Laúd encantado para el campamento (armadura, estadísticas, resistencias).\n- **140:** bastones y orbes nuevos (Soulstaff, Orb of Souls), 45 de Favor.\n- **140:** Arcane Salvager para el campamento (fórmula de botín).\n- **210:** encantamientos de collar, como Poder con hechizos (120 de Favor y Amistoso con la Azeroth Commerce Authority).\n- **Varita brillante:** 180 de Favor y Honorable con la Azeroth Commerce Authority (la habilidad, 275 o 220, según la guía).\n- **300:** Forja arcana y encantamientos de poder con hechizos.\n\nRuta exacta con materiales: data/knowledge/general/professions-enchanting.toml.", note = "Varita brillante: las guías no coinciden en la habilidad (275 o 220)." },
    { heading = "Secundarias", body = "- **Primeros auxilios:** vendas con el paño sobrante; en Forever, también pociones de salud.\n- **Cocina:** comida con +5% de experiencia y la hoguera del campamento (sin hoguera no hay objetos de campamento)." },
    { heading = "Campamento", body = "- La hoguera básica admite 3 objetos; la de Oficial (Cocina 140), 5; la de Experto (Cocina 220), 10.\n- Siéntate o fabrica un minuto al lado para ganar el beneficio.\n- Todos los objetos comparten 1 hora de reutilización.\n- Tus dos profesiones dan objetos a habilidad 20: úsalos cada vez que pares." },
    { heading = "Puntos de Legacy (16 por personaje)", body = "- **Thrill of Adventure:** lo que recomienda ConquestCapped para el personaje principal.\n- **Working Overtime** (5 rangos, +4% de probabilidad de subir habilidad cada uno): si quieres subir profesiones rápido.\n- **Reagent Economy:** tus hechizos de clase dejan de pedir componentes de vendedor y los objetos de campamento básicos son gratis.\n- **Permanence:** tus beneficios largos de grupo duran más.\n- **Field Guide:** menos reutilización del campamento." },
    { heading = "Lógica del asesor", body = "- Ideal de habilidad para tu nivel: **nivel × 5** (máximo 300). Si vas 40 puntos por debajo, la profesión va atrasada.\n- Aviso de tope: a 15 puntos del máximo de tu rango, entrena el siguiente si ya cumples nivel y habilidad.\n- Si tienes una profesión de recolección (Herboristería, que el cliente llama Botánica; Minería; Desuello), el plan es abandonarla." },
  },
})

