})

Senda.Knowledge:Register({
  id = "duo-22-30",
  class = "ANY",
  kind = "page",
  title = "Niveles 22-30: Humedales y Bosque del Ocaso",
  levels = {22, 30},
  order = 360,
  status = "unverified",
  block = {
    { heading = "Dónde", body = "- **Los Humedales:** mazmorra nueva Excavation Site (24-29), con cadenas desde Menethil, Crestagrana y Vallefresno.\n- **Bosque del Ocaso** (Villa Oscura): misiones de no-muertos y huargen. Ojo: la Polimorfia no funciona en no-muertos; ahí el Abisario aguanta y el mago usa la Nova.\n- **Montañas Crestagrana:** la Torre de Ilgalar (misión de clase del mago, Tratado de Ur) y las misiones de orcos.\n- **Mazmorra:** Cavernas de Brazanegra (Vallefresno): Cetro de lápida (varita) para los dos." },
    { heading = "Táctica", body = "Desde el 22 el mago tiene Lanza de hielo: Nova, os alejáis los dos y Lanza. El brujo se queda con el Abisario delante y drena." },
  },
})

